def can_partition_weakly(n, m):
    sets = [set() for _ in range(m)]

    def backtrack(current_val):
        if current_val > n:
            return True

        for i in range(m):
            # Check if adding current_val to sets[i] makes it not weakly sum-free
            # Condition: x + y = current_val for some x, y in sets[i] with x != y and x, y != current_val
            # Since current_val is the largest, x, y != current_val is already satisfied.
            # The only thing is x != y.
            can_add = True
            for x in sets[i]:
                y = current_val - x
                if y in sets[i] and x != y:
                    can_add = False
                    break

            if can_add:
                sets[i].add(current_val)
                if backtrack(current_val + 1):
                    return True
                sets[i].remove(current_val)
        return False

    return backtrack(1)

for m in range(1, 6):
    for n in range(1, 50):
        if not can_partition_weakly(n, m):
            print(f"W({m}) is {n-1}")
            break

