def can_partition(n, m):
    sets = [set() for _ in range(m)]
    def backtrack(current_val):
        if current_val > n:
            return True
        for i in range(m):
            can_add = True
            for x in sets[i]:
                if (current_val - x) in sets[i]:
                    can_add = False
                    break
            if can_add:
                sets[i].add(current_val)
                if backtrack(current_val + 1):
                    return True
                sets[i].remove(current_val)
        return False
    return backtrack(1)

for n in range(10, 20):
    print(f"n={n}, m=3: {can_partition(n, 3)}")
